import { h } from "@stencil/core";

import type { MatrixChartConfig } from "./matrix.d";

import { checkSquare, info, minus, plus } from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { sanitizeHtmlSync } from "../../utils/sanitizeHtml";
import {
	applyStylesFromState,
	isZoomDisabled,
	onCtrlPanelKeyDown,
	setCellStyleFromStateEvent,
} from "./chart-util";

const updateLabelContainer = (
	querySelector: string,
	host,
	paddingTop: number,
	paddingLeft: number,
) => {
	const target = host.shadowRoot.querySelector(querySelector) as SVGGElement;
	if (target) {
		target.setAttribute(
			"transform",
			`translate(${paddingLeft}, ${paddingTop})`,
		);
	}
};

const generateAxis = (
	data,
	blockSize: number,
	gapSize: number,
	labelObj,
	paddingTop: number,
	paddingLeft: number,
	position: "top" | "left" | "right" | "bottom",
	host?: HTMLElement,
) => {
	const positionClass = `axis-${position}`;
	const translateX = position === "left" ? 0 : paddingLeft;
	const translateY = position === "top" ? 0 : paddingTop;
	const labelWidth =
		position === "left" || position === "right" ? labelObj.width : blockSize;
	const labelHeight =
		position === "top" || position === "bottom" ? labelObj.height : blockSize;

	// stenciljs does not hydrate svg
	updateLabelContainer(`g.${positionClass}`, host, paddingTop, paddingLeft);

	const { render = (label) => label, axisTemplate } = labelObj;

	return (
		<g
			class={positionClass}
			transform={`translate(${translateX}, ${translateY})`}
		>
			{data.map((label, index) => {
				const x =
					position === "left" || position === "right"
						? 0
						: index * (blockSize + gapSize);
				const y =
					position === "top" || position === "bottom"
						? 0
						: index * (blockSize + gapSize);
				return (
					<g
						key={`${position}-${label}`}
						width={labelWidth}
						height={labelHeight}
						x={x}
						y={y}
						class="axis-group"
					>
						<foreignObject data-label={label}>
							{axisTemplate ? (
								<div part={positionClass}>{axisTemplate(h, label, index)}</div>
							) : (
								<div
									part={positionClass}
									innerHTML={sanitizeHtmlSync(render(label, index))}
								/>
							)}
						</foreignObject>
					</g>
				);
			})}
		</g>
	);
};

const generateAxisTop = (
	data,
	blockSize,
	gapSize,
	labelTopObj,
	paddingLeft,
	host,
) =>
	generateAxis(
		data,
		blockSize,
		gapSize,
		labelTopObj,
		0,
		paddingLeft,
		"top",
		host,
	);

