import {
	setAxisHoveringState,
	setDefaultItemTooltipTemplate,
} from "./chart-render";
const inheritAttributes = (el: HTMLElement, attributes: string[] = []) => {
	const attributeObject: { [k: string]: string } = {};

	attributes.forEach((attr) => {
		if (el.hasAttribute(attr)) {
			const value = el.getAttribute(attr);
			if (value !== null) {
				attributeObject[attr] = el.getAttribute(attr);
			}
			el.removeAttribute(attr);
		}
	});
	return attributeObject;
};

const setForeignObjectAttributes = (chartRef: HTMLElement) => {
	Array.from(chartRef.querySelectorAll("foreignObject"))
		.map((e) => {
			return { source: e.parentElement, target: e };
		})
		.forEach(({ source, target }) => {
			const attrs = inheritAttributes(source, ["x", "y", "width", "height"]);
			Object.entries(attrs).forEach(([key, value]) => {
				target.setAttribute(key, value);
			});
		});

	Array.from(chartRef.querySelectorAll(".grid-cell"))
		.map((e) => {
			return { source: e.parentElement, target: e };
		})
		.forEach(({ source, target }) => {
			const attrs = inheritAttributes(source, ["x", "y", "width", "height"]);
			Object.entries(attrs).forEach(([key, value]) => {
				target.setAttribute(key, value);
			});
		});
};

const getRowLabels = (data) => {
	return data.reduce((acc, row) => {
		acc.push(row.row);
		return acc;
	}, []);
};

const getColumnLabels = (data) => {
	return data.reduce((acc, row) => {
		row.data.forEach((col) => {
			if (!acc.includes(col.col)) {
				acc.push(col.col);
			}
		});
		return acc;
	}, []);
};

// change order of the data object too
const fillColIfEmpty = (data, colLabels) => {
	return data.map((row) => {
		return {
			row: row.row,
			data: colLabels.map((col) => {
				return row.data.find((d) => d.col === col) || { col };
			}),
		};
	});
};

const calculateContainerDimensions = (
	axis,
	complete2DAry,
	blockSize,
	gapSize,
) => {
	const containerWidth = [axis?.left, axis?.right].reduce(
		(acc, cur) => {
			let width = 0;
			if (cur?.enabled) {
				width = cur.width;
			}
			return width + acc;
		},
		// start with column length
		(complete2DAry[0].data.length + 1) * (blockSize + gapSize),
	);

	const containerHeight = [axis?.top, axis?.bottom].reduce(
		(acc, cur) => {
			let height = 0;
			if (cur?.enabled) {
				height = cur.height;
			}
			return height + acc;
		},
		// start with row length
		complete2DAry.length * (blockSize + gapSize),
	);

	return { containerWidth, containerHeight };
};

const setTargetCellStyle = (
	target: HTMLDivElement,
	gridStyleObject,
	iconSize: number,
) => {
	const { containerStyle = {}, iconStyle = {} } = gridStyleObject || {};

	if (target) {
		if (Object.keys(containerStyle).length !== 0) {
			target.setAttribute("style", "");
			Object.keys(containerStyle).forEach((styleProperty) => {
				target.style[styleProperty] = containerStyle[styleProperty];
			});
		}

		if (target.firstElementChild) {
			if (Object.keys(iconStyle).length !== 0) {
				target.firstElementChild.setAttribute(
					"style",
					`width: ${iconSize}px;height: ${iconSize}px;`,
				);
				Object.keys(iconStyle).forEach((styleProperty) => {
					(target.firstElementChild as HTMLElement).style[styleProperty] =
						iconStyle[styleProperty];
				});
			}
		}
	}
};

const setCellStyleFromStateEvent = (
	event: MouseEvent,
	cellObj,
	allStates,
	viewMode,
	iconSize,
	toggle,
) => {
	const target = event.target as HTMLDivElement;
	if (target.parentElement?.getAttribute("data-selected") === "true") {
		if (cellObj.status && allStates[cellObj.status]) {
			const allCellStateStyles = allStates[cellObj.status].edit;
			if (toggle && allCellStateStyles["selected-hover"]) {
				setTargetCellStyle(
					target,
					allCellStateStyles["selected-hover"],
					iconSize,
				);
			} else {
				setTargetCellStyle(target, allCellStateStyles.selected, iconSize);
			}
		} else {
			// default status
			if (toggle) {
				setTargetCellStyle(
					target,
					allStates.default.edit["selected-hover"],
					iconSize,
				);
			} else {
				setTargetCellStyle(target, allStates.default.edit.selected, iconSize);
			}
		}
	} else {
		if (target && cellObj.status && allStates[cellObj.status]) {
			const allCellStateStyles = allStates[cellObj.status][viewMode];
			if (toggle && allCellStateStyles.hover) {
				setTargetCellStyle(target, allCellStateStyles.hover, iconSize);
			} else {
				setTargetCellStyle(target, allCellStateStyles.default, iconSize);
			}
		} else {
			// default status
			if (toggle) {
				setTargetCellStyle(target, allStates.default[viewMode].hover, iconSize);
			} else {
				setTargetCellStyle(
					target,
					allStates.default[viewMode].default,
					iconSize,
				);
			}
		}
	}
};

const applyStylesFromState = (
	mode,
	statuses,
	selectedItems,
	row,
	col,
	attr,
) => {
	return mode === "view"
		? col.status
			? statuses[col.status]?.view?.default[attr]
			: statuses.default.view?.default[attr]
		: selectedItems[`${row.row}-${col.col}`]
		  ? col.status
				? statuses[col.status]?.edit?.selected[attr]
				: statuses.default.edit.selected[attr]
		  : col.status
			  ? statuses[col.status]?.edit?.default[attr]
			  : statuses.default.edit.default[attr];
};

const getNeighborItemInSameSet = (
	curForeignObj: SVGForeignObjectElement,
	items,
	attr,
	mode: "next" | "prev" = "next",
) => {
	const itemInSameSet = items.filter((item) => {
		return item.getAttribute(attr) === curForeignObj.getAttribute(attr);
	});
	let curIdx = itemInSameSet.indexOf(curForeignObj);

	if (mode === "next") {
		if (curIdx === itemInSameSet.length - 1) {
			curIdx = -1;
		}
	} else {
		if (curIdx === 0) {
			curIdx = itemInSameSet.length;
		}
	}

	return {
		item: itemInSameSet[
			(curIdx + (mode === "next" ? 1 : -1)) % itemInSameSet.length
		],
		idx: itemInSameSet[
			(curIdx + (mode === "next" ? 1 : -1)) % itemInSameSet.length
		].getAttribute("data-index"),
	};
};

const applyItemStyleFromStatus = (
	item: SVGForeignObjectElement,
	status: string,
	mode: string,
	statuses,
	iconSize: number,
) => {
	const target = item.firstElementChild as HTMLDivElement;
	const itemState = item.getAttribute("data-status") || "default";
	const styleState =
		statuses[itemState]?.[mode]?.[status] || statuses.default[mode]?.[status];
	setTargetCellStyle(target, styleState, iconSize);
};

const isZoomDisabled = (isZoomIn: boolean, itemSizes, blockSize) => {
	const index = itemSizes.findIndex((size) => size === blockSize);
	return isZoomIn ? index === itemSizes.length - 1 : index === 0;
};

const onCtrlPanelKeyDown = (event: KeyboardEvent, controlRef) => {
	const focusableElements = [
		...controlRef.querySelectorAll(
			".chart-matrix__control hbr-button:not([disabled])",
		),
	] as HTMLHbrButtonElement[];
	const currentIndex = focusableElements.indexOf(
		event.target as HTMLHbrButtonElement,
	);
	let nextIndex = currentIndex;

	switch (event.key) {
		case "ArrowRight":
			nextIndex = (currentIndex + 1) % focusableElements.length;
			break;
		case "ArrowLeft":
			nextIndex =
				(currentIndex - 1 + focusableElements.length) %
				focusableElements.length;
			break;
		case "ArrowUp":
			nextIndex =
				(currentIndex - 1 + focusableElements.length) %
				focusableElements.length;
			break;
		case "ArrowDown":
			nextIndex = (currentIndex + 1) % focusableElements.length;
			break;
		default:
			return;
	}

	focusableElements[nextIndex]?.setFocus();
	event.preventDefault();
};

const getAllEnabledCells = (chartRef) => {
	return [...chartRef.querySelectorAll(".grid-cell")].filter(
		(r) => r.getAttribute("data-disabled") !== "true",
	) as SVGForeignObjectElement[];
};

const updateEventTargetStyle = (context, event) => {
	const target = event.target as HTMLDivElement;

	const foreignObject = target.parentElement;
	const status = foreignObject.getAttribute("data-status") || "default";

	const allStates = context.fullConfig.statuses;
	if (target.getAttribute("data-selected") === "true") {
		if (target && allStates[status]) {
			setTargetCellStyle(
				target,
				allStates[status].edit.default,
				context.gridSize.iconSize,
			);
		} else {
			// default status
			setTargetCellStyle(
				target,
				allStates.default.edit.default,
				context.gridSize.iconSize,
			);
		}
	} else {
		if (target && allStates[status]) {
			setTargetCellStyle(
				target,
				allStates[status].edit["selected-hover"],
				context.gridSize.iconSize,
			);
		} else {
			// default status
			setTargetCellStyle(
				target,
				allStates.default.edit["selected-hover"],
				context.gridSize.iconSize,
			);
		}
	}
};

const getModeEditEventHandlers = (context) => {
	return {
		onClick: (event: MouseEvent) => {
			const target = event.target as HTMLDivElement;
			const foreignObject = target.parentElement;
			const row = foreignObject.getAttribute("data-row");
			const col = foreignObject.getAttribute("data-col");
			const status = foreignObject.getAttribute("data-status") || "default";
			updateEventTargetStyle(context, event);

			// deep clone
			const dict = JSON.parse(JSON.stringify(context.selectedItems));
			if (context.selectedItems[`${row}-${col}`]) {
				delete dict[`${row}-${col}`];
				context.selectedItems = dict;
			} else {
				dict[`${row}-${col}`] = { status };
				context.selectedItems = dict;
			}
			context.config?.eventListeners?.edit?.onClick?.(
				event,
				context.selectedItems,
			);
			// @deprecated
			context.config?.onSelect?.(event, context.selectedItems);
		},
		onMouseEnter: (event: MouseEvent) => {
			const foreignObject = (event.target as HTMLElement).parentElement;
			const row = foreignObject.getAttribute("data-row");
			const col = foreignObject.getAttribute("data-col");

			setAxisHoveringState(context.el.shadowRoot, row, col, true);
			context.config?.eventListeners?.edit?.onMouseEnter?.(event);
		},
		onMouseMove: (event: MouseEvent) => {
			context.config?.eventListeners?.edit?.onMouseMove?.(event);
		},
		onMouseLeave: (event: MouseEvent) => {
			const foreignObject = (event.target as HTMLElement).parentElement;
			const row = foreignObject.getAttribute("data-row");
			const col = foreignObject.getAttribute("data-col");

			setAxisHoveringState(context.el.shadowRoot, row, col, false);
			context.config?.eventListeners?.edit?.onMouseLeave?.(event);
		},
		onFocus: (event: FocusEvent) => {
			context.config?.eventListeners?.edit?.onFocus?.(event);
		},
		onBlur: (event: FocusEvent) => {
			context.config?.eventListeners?.edit?.onBlur?.(event);
		},
	};
};

const getModeViewEventHandlers = (
	context,
	complete2DAry,
	hydrationFunction,
) => {
	return {
		onMouseEnter: (event: MouseEvent) => {
			const foreignObject = (event.target as HTMLElement).parentElement;
			const row = foreignObject.getAttribute("data-row");
			const col = foreignObject.getAttribute("data-col");
			const targetAxisItem = complete2DAry
				.find((r) => r.row === row)
				?.data.find((c) => c.col === col);

			if (targetAxisItem?.status === "disabled") {
				return;
			}
			context.hoveredItems = { row, col, obj: targetAxisItem };
			if (context.fullConfig.tooltipItemTemplate) {
				context.tooltipContent = context.fullConfig.tooltipItemTemplate(
					hydrationFunction,
					row,
					col,
					targetAxisItem,
					context.fullConfig,
				);
				context.tooltipRef.open = true;
				context.tooltipRef.anchor = event.target as HTMLElement;
			} else {
				context.tooltipContent = setDefaultItemTooltipTemplate(
					hydrationFunction,
					row,
					col,
					targetAxisItem,
					context.fullConfig,
				);
				context.tooltipRef.open = true;
				context.tooltipRef.anchor = event.target as HTMLElement;
			}
			setAxisHoveringState(context.el.shadowRoot, row, col, true);
			context.config?.eventListeners?.view?.onMouseEnter?.(event);
		},
		onMouseMove: (event: MouseEvent) => {
			context.config?.eventListeners?.view?.onMouseMove?.(event);
		},
		onMouseLeave: (event: MouseEvent) => {
			const foreignObject = (event.target as HTMLElement).parentElement;
			const row = foreignObject.getAttribute("data-row");
			const col = foreignObject.getAttribute("data-col");

			setAxisHoveringState(context.el.shadowRoot, row, col, false);
			context.tooltipRef.open = false;
			context.config?.eventListeners?.view?.onMouseLeave?.(event);
		},
		onFocus: (event: FocusEvent) => {
			context.config?.eventListeners?.view?.onFocus?.(event);
		},
		onBlur: (event: FocusEvent) => {
			context.config?.eventListeners?.view?.onBlur?.(event);
		},
		onClick: (event: MouseEvent) => {
			context.config?.eventListeners?.view?.onClick?.(event);
		},
	};
};

const getContainerKeyboardEvents = (context) => {
	return {
		onKeyDown: (event: KeyboardEvent) => {
			let data = null;
			const items = Array.from(
				context.chartRef.querySelectorAll(".grid-cell"),
			) as SVGForeignObjectElement[];

			if (event.key === "Enter" || event.key === " ") {
				const target = event.target as HTMLDivElement;
				const foreignObject = target.parentElement;
				const row = foreignObject.getAttribute("data-row");
				const col = foreignObject.getAttribute("data-col");
				const status = foreignObject.getAttribute("data-status") || "default";
				updateEventTargetStyle(context, event);

				// deep clone
				data = JSON.parse(JSON.stringify(context.selectedItems));
				if (context.selectedItems[`${row}-${col}`]) {
					delete data[`${row}-${col}`];
					context.selectedItems = data;
				} else {
					data[`${row}-${col}`] = { status };
					context.selectedItems = data;
				}

				event.stopPropagation();
				event.preventDefault();
			} else {
				const handleArrowKey = (
					direction: "next" | "prev",
					axis: "data-col" | "data-row",
				) => {
					const prev = items[context.keyboardFocusedIndex];
					if (prev) {
						applyItemStyleFromStatus(
							prev,
							prev.getAttribute("data-selected") === "true"
								? "selected"
								: "default",
							context.mode,
							context.fullConfig.statuses,
							context.gridSize.iconSize,
						);
						prev.firstElementChild.removeAttribute("tabindex");
						(prev.firstElementChild as HTMLDivElement).blur();
					}

					let next = getNeighborItemInSameSet(
						prev || items[0],
						items,
						axis,
						direction,
					);
					while (next.item.getAttribute("data-disabled") === "true") {
						next = getNeighborItemInSameSet(next.item, items, axis, direction);
					}

					context.keyboardFocusedIndex = Number.parseInt(next.idx, 10);
					applyItemStyleFromStatus(
						next.item,
						"focused",
						"view",
						context.fullConfig.statuses,
						context.gridSize.iconSize,
					);
					next.item.firstElementChild.setAttribute("tabindex", "0");
					next.item.firstElementChild.focus();
					event.stopPropagation();
				};

				switch (event.key) {
					case "ArrowRight":
						handleArrowKey("next", "data-row");
						break;
					case "ArrowLeft":
						handleArrowKey("prev", "data-row");
						break;
					case "ArrowDown":
						handleArrowKey("next", "data-col");
						break;
					case "ArrowUp":
						handleArrowKey("prev", "data-col");
						break;
				}
			}
			context.config?.eventListeners?.[context.mode]?.onKeyDown?.(event, data);
		},
		onKeyUp: (event: KeyboardEvent) => {
			context.config?.eventListeners?.[context.mode]?.onKeyUp?.(
				event,
				context.selectedItems,
			);
		},
	};
};

export {
	setForeignObjectAttributes,
	getRowLabels,
	getColumnLabels,
	fillColIfEmpty,
	calculateContainerDimensions,
	setCellStyleFromStateEvent,
	setTargetCellStyle,
	applyStylesFromState,
	getNeighborItemInSameSet,
	applyItemStyleFromStatus,
	isZoomDisabled,
	onCtrlPanelKeyDown,
	getAllEnabledCells,
	getModeEditEventHandlers,
	getModeViewEventHandlers,
	getContainerKeyboardEvents,
};
